/* Control centre: Administration, Workflows & data, Project R&R policy. Mirrors pages/admin plus the plan's additions. */
let IMPORT_STEP = 0;
function viewAdmin(tab) {
  crumbs([["Administration"]]);
  const head = `<div class="ph"><div class="titles"><h1>Keep the organisation ready for good data</h1><p class="sub">Named accounts, trusted identities and a visible audit trail</p></div></div>
  ${tabs([["access", "People & access"], ["grants", "Temporary access"], ["imports", "Imports"], ["audit", "Audit history"]], tab, (id) => `#/admin/${id}`)}`;
  if (tab === "grants") return head + `<div class="split wide-side">${panel("Active grants", table(["Recipient", "Project", "Permission", "Reason", "Expires"], S.grants.map((g) => `<tr><td>${chip(g.to)}</td><td>${g.project}</td><td>${g.permission}</td><td class="wrap">${esc(g.reason)}</td><td>${fd(g.expires)}</td></tr>`), "No active grants"), { pad: false, meta: "Work access only. Grants never include private performance or R&R scores." })}
    ${panel("Grant temporary work access", `<div class="stack">${field("Named recipient", "g_to", `<select class="input" id="g_to">${personOptions("")}</select>`, { req: true })}${field("Project", "g_p", `<select class="input" id="g_p">${S.projects.map((p) => `<option>${p.code}</option>`).join("")}</select>`, { req: true })}
      ${field("Permission", "g_perm", `<select class="input" id="g_perm"><option>View</option><option>Comment</option><option>Update tasks</option></select>`, { req: true })}${field("Reason", "g_r", `<input class="input" id="g_r">`, { req: true })}${field("Expires", "g_e", `<input class="input" type="date" id="g_e" min="${TODAY}">`, { req: true })}${btn("Grant access", "grantAdd", { primary: true })}</div>`)}</div>`;
  if (tab === "imports") return head + viewImport();
  if (tab === "audit") return head + panel("Audit history", table(["Time", "Actor", "Action", "Record", "Reason"], S.audit.map((a) => `<tr><td>${esc(a.at)}</td><td>${esc(pname(a.by))}</td><td>${esc(a.action.replace(/_/g, " "))}</td><td class="mono">${a.record}</td><td class="wrap">${esc(a.reason || "—")}</td></tr>`)), { pad: false, meta: "Append-only. Even Admin can't edit or delete an event." });
  const noFinance = !S.personas.some((x) => x.fns.includes("Finance confirmer"));
  return head + `${noFinance ? callout("warn", "No Finance confirmer is tagged.", "Value confirmations wait, and the Finance gate fails until someone holds this function.") : ""}
  ${panel("Named account directory", table(["Person", "Role", "Scope", "Project R&R functions (click to toggle)", "State"], S.accounts.map((a) => { const per = S.personas.find((x) => x.emp === a.emp);
    return `<tr><td>${chip(a.emp)}<span class="sub">${esc(a.email)}</span></td><td>${a.role}</td><td class="wrap small">${esc(a.scope)}</td><td class="wrap">${per ? FUNCTIONS.map((f) => `<span class="fn-chip ${per.fns.includes(f) ? "on" : ""}" data-fn="${per.id}|${f}">${f}</span>`).join("") : `<span class="muted small">No functions</span>`}</td><td>${badge(a.active ? "Validated" : "Rejected").replace(a.active ? "Validated" : "Rejected", a.active ? "Active" : "Disabled")}</td></tr>`; })),
    { pad: false, meta: "Managers, HODs, Team Leads and Admins only. No employee or shared logins.", tools: btn("Provision account", "toast:Provision: choose the employee identity (ID, designation, department), company email, role and reason. Audited.", { sm: true }),
      foot: `<span class="note">Functions add Project R&amp;R duties to an existing account, never a new login. A Panel member in a project's RACI can't approve that project's scorecard.</span>` })}`;
}
function viewImport() {
  const steps = ["Upload", "Map", "Validate", "Confirm", "Result"];
  const issues = [["Critical", "Project_Register / PRJ-D04", "Priority missing", "Choose High, Medium or Low"], ["High", "Employee_Master / EMP-0118", "Same name, different identity: Naveen Kumar", "Confirm HRMS ID and department"],
    ["High", "Workflow_Templates / Email campaign", "Reviewer is an assignee or unresolved on stages 2, 4, 5, 6", "Select independent named reviewers"], ["High", "RACI.xlsx Sheet3", "Mukesh Thakur is not in the org chart", "Add the employee record or name another champion"],
    ["Medium", "Tracker_Cleaned / 24 rows", "Legacy Completed without a reliable date", "Imported as In review, not accepted output"]];
  const body = [
    `<p>Choose the corrected workbook. Nothing is written until you confirm.</p><div class="row mt"><span class="badge outline">PT_RR_Corrected_Data.xlsx · 12 sheets</span>${btn("Use this file", "importNext", { primary: true, sm: true })}</div>`,
    `${table(["Sheet", "Maps to", "Rows"], [["Employee_Master", "Employees", 325], ["Project_Register", "Projects", 60], ["Tracker_Cleaned", "Tasks and assignments", 175], ["Workflow_Templates", "Templates and stages", 6], ["Risk_Register", "Template risks", 12]].map((r) => `<tr><td>${r[0]}</td><td>${r[1]}</td><td class="n">${r[2]}</td></tr>`))}<div class="row mt">${btn("Run dry run", "importNext", { primary: true, sm: true })}</div>`,
    `${table(["Severity", "Source", "Issue", "Fix / rule"], issues.map((r) => `<tr><td>${badge(r[0] === "Critical" ? "Critical" : r[0] === "High" ? "High" : "Medium")}</td><td class="small">${r[1]}</td><td class="wrap">${r[2]}</td><td class="wrap small">${r[3]}</td></tr>`))}<p class="note mt">Critical identity, share and reviewer conflicts must be resolved before commit. Flags are kept, never silently fixed.</p><div class="row mt">${btn("Continue", "importNext", { primary: true, sm: true })}</div>`,
    `${callout("warn", "1 critical issue remains.", "PRJ-D04 will import with Priority missing and stay blocked from editing until a priority is chosen.")}<div class="row">${btn("Commit import", "importNext", { primary: true, sm: true })}${btn("Back", "importBack", { sm: true })}</div>`,
    `${callout("ok", "Imported.", "Batch IMP-2026-10-22 · 60 projects, 109 tasks, 175 assignments, 1 template, 12 risks. Per-row results are kept with the batch.")}${btn("Start again", "importReset", { sm: true })}`,
  ][IMPORT_STEP];
  return panel("Import dry run", `<div class="steps" style="margin-bottom:16px">${steps.map((s, i) => `<span class="${i < IMPORT_STEP ? "done" : i === IMPORT_STEP ? "now" : ""}"><span class="dot">${i < IMPORT_STEP ? "✓" : i + 1}</span>${s}</span>`).join("")}</div>${body}`, { meta: "Upload › Map › Validate › Confirm › Result" });
}

function viewWorkflows(tab) {
  crumbs([["Workflows & data"]]);
  const head = `<div class="ph"><div class="titles"><h1>Design the workflow. Trust the inputs.</h1><p class="sub">Templates, calendars and validated sources · no live connector assumed</p></div></div>
  ${tabs([["templates", "Workflow templates"], ["raci", "RACI & review"], ["calendar", "Working calendar"], ["inputs", "Input validation"]], tab, (id) => `#/workflows/${id}`)}`;
  if (tab === "calendar") { const start = Q.get("s") || TODAY, days = Number(Q.get("d") || 9);
    return head + `<div class="grid grid-2">${panel("Use one business calendar for scheduling", table(["Holiday", "Date"], S.holidays.map((h) => `<tr><td>${esc(h.name)}</td><td>${fd(h.day)}</td></tr>`)) + `<div class="row mt"><input class="input" style="width:220px" id="h_name" placeholder="Approved holiday name"><input class="input" type="date" style="width:160px" id="h_day">${btn("Add holiday", "holidayAdd", { sm: true })}</div>`, { meta: "India (IST) · Mon–Fri" })}
      ${panel("Deadline preview", `<div class="form-grid"><div class="field"><label>Start</label><input class="input" type="date" data-nav="s" value="${start}"></div><div class="field"><label>Business days</label><input class="input" type="number" data-nav="d" value="${days}"></div></div>
        <p class="mt">Due: <b>${fd(addBdays(start, days))}</b></p><p class="note">Start + the maximum business-day SLA using this calendar. The Email campaign template is 9 days target, 14 maximum.</p>`)}</div>`; }
  if (tab === "inputs") return head + `${callout("warn", "Source selection is pending.", "Manual records or batch imports, without claiming a live HRMS, LMS or CRM feed. Draft › Submitted › Validated or Returned, with an independent validator.")}
    ${panel("Project R&amp;R inputs", table(["Project", "Input", "Value", "Author", "Validator function", "State", ""], (S.rrInputs || []).map((x, i) => `<tr><td>${x.project}</td><td>${esc(x.kind)}</td><td>${esc(x.value)}</td><td>${esc(pname(x.by))}</td><td>${x.fn}</td><td>${badge(x.state)}</td>
      <td>${x.state === "Submitted" ? (has(x.fn) || (isAdmin() && x.fn !== "Finance confirmer") ? `${btn("Validate", `inputDecide:${i}:Validated`, { sm: true })} ${btn("Return", `inputDecide:${i}:Returned`, { sm: true })}` : `<span class="note">Needs ${x.fn}</span>`) : ""}</td></tr>`)), { pad: false, meta: "Value confirmations, quality inputs and manual SLA counts. The author can't validate their own input." })}`;
  const raci = tab === "raci";
  return head + [EMAIL_TEMPLATE, CS_TEMPLATE].map((t) => {
    const conflicts = t.stages.filter((s) => (s.validator && !s.vRule && s.R.includes(s.validator)) || s.A === "MUKESH" || !s.validator).length;
    return `<div class="mb">${panel(t.name, raci && t.sla ? table(["Step", "Responsible", "Accountable (one)", "Consulted / Informed", "Validator", "Conflicts", ""], t.stages.map((s) => {
        const c = [...(s.A && EMP[s.A]?.missing ? ["A not in org chart"] : []), ...(s.validator && !s.vRule && s.R.includes(s.validator) ? ["Reviewer is R"] : []), ...((s.C || []).filter((x) => s.R.includes(x)).length ? ["Same person R and C"] : [])];
        return `<tr><td class="mono">${s.step}</td><td>${s.R.map(chip).join(" ")}</td><td>${chip(s.A)}</td><td class="wrap">${(s.C || []).map(chip).join(" ") || "—"} <span class="muted">/</span> ${(s.I || []).map(chip).join(" ")}</td>
          <td>${s.vRule ? `<select class="select-sm" aria-label="Validator rule"><option>Rule: head of requesting dept</option><option>Rule: manager of requester</option><option>Named person</option></select>` : chip(s.validator)}</td><td>${c.length ? c.map((x) => `<span class="badge bad">${x}</span>`).join(" ") : `<span class="badge ok">None</span>`}</td><td>${btn("Resolve", `toast:Resolve RACI for step ${s.step}: pick named R, one A, an independent reviewer (or a rule) and a change reason. Audited.`, { sm: true })}</td></tr>`; }))
      : table(["Step", "Stage", "SLA target / max", "Effort", "Checklist", "Evidence", "Risks"], t.stages.map((s) => `<tr><td class="mono">${s.step}</td><td><b>${esc(s.name)}</b>${s.flag ? `<span class="sub warn-txt">${esc(s.flag)}</span>` : ""}</td><td>${s.sla ? `${s.sla[0]} / ${s.sla[1]} bd` : `<span class="unavail">Not defined</span>`}</td><td>${s.effort ? `${s.effort[0]}–${s.effort[1]} h` : "—"}</td><td class="wrap small">${esc(s.checklist || "To define")}</td><td class="wrap small">${esc(s.evidence || "—")}</td><td class="small">${t.risks?.[s.step]?.codes ?? "—"}</td></tr>`)),
      { pad: false, meta: `${t.state}${t.sla ? ` · ${t.sla[0]} bd target, ${t.sla[1]} max · ${t.effort[0]}–${t.effort[1]} h` : ""} · ${conflicts} stage(s) with conflicts`, tools: btn("Activate template", `toast:Activation blocked: ${conflicts} stage(s) still have RACI or reviewer conflicts`, { sm: true, primary: true }),
        foot: raci ? `<span class="note">One named A per step, one RACI letter per person per step, and an assignee can't review. Source conflicts block activation. Approval waiting belongs to the approval stage and its A.</span>` : "" })}</div>`; }).join("");
}

function viewPolicy() {
  crumbs([["Project R&R policy"]]);
  const P = [["P1", "Flat −2, or −4 for slips over 10 working days", "Flat −2"], ["P2", "Timelines 25 / Quality 25, or 20 / 30", "25 / 25"], ["P3", "Pool rates and annual cap", "2 / 2.5 / 3%, cap not set"], ["P4", "Who sets non-revenue value targets", "Sponsor; campaigns use conversions"],
    ["P5", "Severity → critical error", "Major = critical"], ["P6", "Rework % source", "Computed from stage effort for template work"], ["P7", "Disciplinary and probation source", "None, so Unknown blocks cash"], ["P8", "Pilot projects", "3–5 live projects for one quarter"],
    ["P9", "Collaboration: §13 example (+3) vs §3.2 rule (+4)", "§3.2 rule, HR to confirm"], ["P10", "Recurring template work", "Quarterly programme"], ["P11", "Escalation miss on stages of 3 bd or less", "Flag before half the stage SLA"], ["P12", "Factor from planned effort share", "≥40% 1.0 · 20–40% 0.75 · <20% 0.5"], ["P13", "Outside approver misses stage SLA", "Client-caused (excused)"], ["P14", "Stage-level A at project level", "Workstream lead (R)"]];
  return `<div class="ph"><div class="titles"><h1>Project R&amp;R policy · PR-1</h1><p class="sub">Versioned configuration. Score-affecting changes need a second Admin. Locked scorecards keep the version they were scored with.</p></div>
    <div class="actions">${btn("Approve as second Admin", "x", { primary: true, disabled: true, title: "You authored this version; a different Admin must approve" })}</div></div>
  <div class="proposed">${icon(I.warn)}<span><b>Proposed, not activated.</b> Authored by Deepjyot Tiwari on 22 Oct 2026. Approval is disabled for the author.</span></div>
  <div class="grid grid-2">${panel("Slabs", table(["Parameter", "Slabs"], [["Revenue / value (30)", "≥100% 30 · 90–99 24 · 80–89 18 · 70–79 10 · <70 0"], ["Timelines (25)", "≥90% 25 · 80–89 20 · 70–79 14 · 60–69 8 · <60 0"], ["TAT / SLA (20)", "≥95% 20 · 90–94 16 · 80–89 11 · 70–79 6 · <70 0"], ["Rework (10)", "≤5% 10 · 6–10 7 · 11–15 4 · >15 0"], ["Errors after go-live (8)", "0 crit ≤2 minor 8 · 0 crit 3–5 minor 5 · 1 crit 2 · ≥2 crit 0"], ["Satisfaction (7)", "≥4.5 7 · 4.0–4.4 5 · 3.5–3.9 3 · <3.5 0"]].map((r) => `<tr><td>${r[0]}</td><td class="wrap">${esc(r[1])}</td></tr>`)), { pad: false })}
    ${panel("Caps, bands and units", `<dl class="kv"><dt>Delay penalty</dt><dd>−2 · escalation miss on top of another reason −2 more</dd><dt>Caps</dt><dd>−4 / task · −20 / project · −10 / person</dd><dt>Recovery credit</dt><dd>+1 (max +6)</dd><dt>Bonus</dt><dd>≤ +10, only if Quality ≥ 15</dd><dt>Bands</dt><dd>Platinum 90 · Gold 80 · Silver 70 · Bronze 60</dd><dt>Payout %</dt><dd>100 / 80 / 60 / 0 / 0</dd><dt>Units</dt><dd>A 3 · R 2×factor · C 0.5 (C pool ≤ 20%)</dd><dt>Pool rates</dt><dd>2% · 2.5% · 3%</dd></dl>`)}</div>
  <div class="mt">${panel("Delay reasons", table(["Code", "Reason", "Counts as", "When to use"], DELAY_REASONS.map((r) => `<tr><td class="mono">${r.code}</td><td><b>${esc(r.label)}</b></td><td>${r.ctrl ? `<span class="bad-txt">Controllable · −2</span>` : `<span class="ok-txt">Excused · evidence needed</span>`}</td><td class="wrap small">${esc(r.help)}</td></tr>`)), { pad: false, meta: "One late task = one delay · the PMO validator confirms the reason" })}</div>
  <div class="sec-title"><h2>Open decisions</h2><span class="meta">Defaults apply until answered</span></div>${panel("", table(["#", "Decision", "Default"], P.map((r) => `<tr><td class="mono">${r[0]}</td><td class="wrap">${esc(r[1])}</td><td class="wrap">${esc(r[2])}</td></tr>`)), { pad: false }).replace('<div class="panel-h"><h2></h2></div>', "")}`;
}
